def insert_dash(num: int) -> str:
    s = str(num)
    result = []
    i = 0
    while i < len(s):
        digit = int(s[i])
        result.append(s[i])
        if i + 1 < len(s):
            next_digit = int(s[i + 1])
            if digit % 2 != 0 and next_digit % 2 != 0:
                result.append('-')
        i += 1
    return ''.join(result)
